css:
:root {
  --panel-heading: #52758B;
  --panel-text: #213B4D;
  --panel-accent: #0A638F;
  --panel-secondary: #607D91;

  --field-border: #718A9C;
  --field-divider: #95A9B8;
  --section-line: #B8C7D2;

  --logo-dark: #6F7271;
  --logo-light: #9EA1A2;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  border: none;
  background: transparent !important;
}

.line-panel-widget {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
  overflow: hidden;

  border: none;
  background: transparent;
  box-shadow: none;
  pointer-events: none;
}

.line-panel-svg {
  display: block;
  width: 100%;
  height: 100%;

  background: transparent;
  font-family: "Segoe UI", Arial, sans-serif;
  shape-rendering: geometricPrecision;
}

/* Encabezado */
.panel-heading {
  fill: var(--panel-heading);
  font-size: 19px;
  font-weight: 600;
  letter-spacing: 3px;
  text-anchor: middle;
}

.panel-title {
  fill: var(--panel-text);
  font-size: 34px;
  font-weight: 700;
  letter-spacing: 0.3px;
  text-anchor: middle;
}

.panel-number {
  fill: var(--panel-accent);
  font-size: 38px;
  font-weight: 700;
}

.heading-accent {
  fill: none;
  stroke: var(--panel-accent);
  stroke-width: 3;
  stroke-linecap: round;
}

/* Logotipo */
.logo-dark {
  fill: var(--logo-dark);
}

.logo-light {
  fill: var(--logo-light);
}

.logo-caption {
  fill: var(--logo-dark);
  font-family: Arial, Helvetica, sans-serif;
  font-size: 56px;
  font-weight: 700;
  text-anchor: start;
}

/* Separación de registros */
.section-line {
  fill: none;
  stroke: var(--section-line);
  stroke-width: 1;
}

.section-label {
  fill: var(--panel-secondary);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 1.1px;
  text-anchor: middle;
  dominant-baseline: central;
}

/* Campos transparentes con bordes ligeramente más oscuros */
.field-outline {
  fill: none;
  stroke: var(--field-border);
  stroke-width: 1.2;
}

.field-divider {
  fill: none;
  stroke: var(--field-divider);
  stroke-width: 1;
}

.field-label {
  fill: var(--panel-text);
  font-size: 18px;
  font-weight: 500;
  text-anchor: middle;
  dominant-baseline: central;
}

.field-unit {
  fill: var(--panel-heading);
  font-size: 18px;
  font-weight: 600;
  text-anchor: middle;
  dominant-baseline: central;
}

/* RESET conserva su azul original */
.reset-outline {
  fill: none;
  stroke: var(--panel-accent);
  stroke-width: 1.5;
}

.reset-label {
  fill: var(--panel-accent);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.7px;
  text-anchor: middle;
  dominant-baseline: central;
}

js:
"use strict";

(function () {
  /*
   * Solo centra el contenido del widget.
   *
   * No recibe datos del PLC.
   * Los campos permanecen vacíos.
   * RESET no tiene funcionalidad.
   */

  function centerContent() {
    const svg = document.querySelector(".line-panel-svg");
    const content = document.querySelector(".panel-content");

    if (!svg || !content) return;

    const bounds = content.getBBox();
    const viewBox = svg.viewBox.baseVal;

    if (bounds.width <= 0 || bounds.height <= 0) return;

    const offsetX =
      viewBox.x + viewBox.width / 2 -
      (bounds.x + bounds.width / 2);

    const offsetY =
      viewBox.y + viewBox.height / 2 -
      (bounds.y + bounds.height / 2);

    content.setAttribute(
      "transform",
      "translate(" + offsetX + " " + offsetY + ")"
    );
  }

  function initialize() {
    requestAnimationFrame(centerContent);

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(function () {
        requestAnimationFrame(centerContent);
      });
    }

    window.addEventListener("resize", centerContent);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
